def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_c = 0
    for x in opp:
        if x == 'C':
            opp_c += 1
    opp_d = n - opp_c

    my_d = 0
    for x in me:
        if x == 'D':
            my_d += 1

    if n == 1:
        return 'C' if opp[-1] == 'C' else 'D'

    last_me = me[-1]
    last_opp = opp[-1]

    ac_c = 0
    ac_d = 0
    ad_c = 0
    ad_d = 0
    for i in range(1, n):
        if me[i - 1] == 'C':
            if opp[i] == 'C':
                ac_c += 1
            else:
                ac_d += 1
        else:
            if opp[i] == 'C':
                ad_c += 1
            else:
                ad_d += 1

    sc = ac_c + ac_d
    sd = ad_c + ad_d

    w = min(12, n)
    recent_d = 0
    for x in opp[n - w:]:
        if x == 'D':
            recent_d += 1

    w5 = min(5, n)
    recent5_d = 0
    for x in opp[n - w5:]:
        if x == 'D':
            recent5_d += 1

    opp_d_streak = 0
    for x in reversed(opp):
        if x == 'D':
            opp_d_streak += 1
        else:
            break

    provoked = False
    if opp_d_streak > 0:
        idx = n - opp_d_streak - 1
        if idx >= 0 and me[idx] == 'D':
            provoked = True

    if opp_c == 0:
        return 'D'

    if last_opp == 'D' and not provoked and opp_d_streak >= 2:
        return 'D'

    if opp_d * 100 >= n * 72 and recent_d * 10 >= w * 7:
        if not (provoked and opp_c * 100 >= n * 35 and opp_d_streak <= 5):
            return 'D'

    if opp_d == 0:
        if sd >= 1 and ad_c > ad_d:
            if sd >= 4 and ad_d * 10 <= sd * 2:
                return 'D' if rng.random() < 0.95 else 'C'
            if sd >= 2:
                return 'D' if rng.random() < 0.75 else 'C'
            return 'D' if rng.random() < 0.5 else 'C'

        if last_me == 'D' and last_opp == 'C':
            return 'C'

        if my_d == 0 and 8 <= n <= 90 and rng.random() < 0.03:
            return 'D'

        return 'C'

    if sc >= 3 and ac_d * 10 >= sc * 7 and recent5_d >= 2 and last_opp == 'D' and provoked:
        return 'D'

    if last_opp == 'C':
        if last_me == 'D':
            if sc >= 3 and ac_d * 3 >= sc * 2 and opp_d * 100 >= n * 40:
                return 'D' if rng.random() < 0.8 else 'C'

            if sd >= 3:
                if ad_d * 10 <= sd * 2 and opp_c * 100 >= n * 55:
                    return 'D' if rng.random() < 0.9 else 'C'
                if ad_d * 10 <= sd * 5 and opp_c * 100 >= n * 65 and recent5_d <= 1:
                    return 'D' if rng.random() < 0.55 else 'C'

            if sd >= 2 and ad_c > ad_d and opp_c * 100 >= n * 65 and recent5_d <= 1:
                return 'D' if rng.random() < 0.65 else 'C'
            if sd >= 1 and ad_c > ad_d and opp_c * 100 >= n * 75 and recent5_d == 0:
                return 'D' if rng.random() < 0.35 else 'C'

            if opp_d * 100 >= n * 55 or recent_d * 3 >= w * 2:
                return 'D'
            return 'C'

        if sc >= 4 and ac_d * 10 >= sc * 5:
            return 'D' if rng.random() < 0.85 else 'C'
        if sc >= 3 and ac_d * 10 >= sc * 4 and recent_d * 10 >= w * 4:
            return 'D'

        if sd >= 3:
            if ad_d * 10 <= sd * 2 and opp_c * 100 >= n * 55 and recent5_d <= 1:
                return 'D' if rng.random() < 0.85 else 'C'
            if ad_d * 10 <= sd * 4 and opp_c * 100 >= n * 70 and recent5_d == 0:
                return 'D' if rng.random() < 0.45 else 'C'
            if ad_d * 10 <= sd * 6 and opp_c * 100 >= n * 80 and recent5_d == 0 and n <= 90:
                return 'D' if rng.random() < 0.2 else 'C'
        elif sd == 2 and ad_c >= 1 and ad_d == 0 and opp_c * 100 >= n * 65 and recent5_d == 0:
            return 'D' if rng.random() < 0.6 else 'C'
        elif sd == 1 and ad_c == 1 and ad_d == 0 and opp_c * 100 >= n * 60 and recent5_d == 0:
            return 'D' if rng.random() < 0.5 else 'C'

        if opp_d * 100 >= n * 50 and recent_d * 10 >= w * 5:
            return 'D' if rng.random() < 0.65 else 'C'

        return 'C'

    if last_me == 'D':
        if sc >= 4 and ac_d * 10 >= sc * 7:
            return 'D' if rng.random() < 0.75 else 'C'

        if opp_c * 100 >= n * 38 and recent5_d <= 2 and opp_d_streak <= 3:
            return 'C' if rng.random() < 0.9 else 'D'
        if opp_c * 100 >= n * 30 and recent5_d <= 3 and opp_d_streak <= 4 and rng.random() < 0.55:
            return 'C'

        return 'D'

    if provoked:
        if sc >= 4 and ac_d * 10 >= sc * 7:
            return 'D' if rng.random() < 0.7 else 'C'

        if opp_c * 100 >= n * 45 and recent5_d <= 2 and opp_d_streak <= 2:
            return 'C'
        if opp_c * 100 >= n * 35 and recent5_d <= 3 and opp_d_streak <= 3:
            return 'C' if rng.random() < 0.75 else 'D'
        if opp_c * 100 >= n * 30 and recent5_d <= 4 and opp_d_streak <= 4 and rng.random() < 0.45:
            return 'C'

        return 'D'

    if opp_c * 100 >= n * 88 and opp_d_streak == 1 and recent5_d == 1 and rng.random() < 0.12:
        return 'C'

    return 'D'
